// Turns raw V8 coverage into a Codecov report over every source file its flag
// covers: a file that no test loads is reported at 0% instead of being left
// out, so the total is the coverage of the whole codebase.
//
//   node .github/scripts/coverage-report.mjs <flag> <raw dir>...
//
// A raw dir holds NODE_V8_COVERAGE output (Node processes: unit and smoke
// tests, the Next.js server under e2e) or the browser coverage that
// e2e/infra/coverage.ts saves from Playwright pages. The report is written to
// coverage/<flag>/ (codecov.json for the upload, index.html to browse).
//
// COVERAGE_ROOT points it at another checkout (the tests use a scratch one).

import { createHash } from 'node:crypto';
import { appendFileSync, existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = process.env.COVERAGE_ROOT
  ? path.resolve(process.env.COVERAGE_ROOT) + path.sep
  : fileURLToPath(new URL('../..', import.meta.url));

// The source code the coverage is measured over. Everything else (tests,
// generated code, config, tooling) is out of scope.
const SOURCES = [
  /^(app|lib|components)\/.+\.tsx?$/,
  /^(auth|proxy)\.ts$/,
  /^desktop\/main\.cjs$/,
  /^desktop\/(lib|scripts)\/.+\.[cm]?js$/,
  /^mobile\/capacitor\.config\.ts$/,
];
const NOT_SOURCES = [
  /\.(test|smoke|spec)\.[cm]?[jt]sx?$/,
  /\.d\.ts$/,
  // ANTLR output, regenerated by `npm run generate:grammar`.
  /^lib\/falkordb-cypher\/generated\//,
];

/** Whether a repository-relative path is source code the coverage counts. */
export function isSourceFile(relPath) {
  return SOURCES.some((re) => re.test(relPath)) && !NOT_SOURCES.some((re) => re.test(relPath));
}

// Each flag reports only on the code its workflow tests, and that workflow
// runs whenever that code changes. Codecov carries a flag forward from an
// earlier commit when its workflow did not run, so its lines must never
// belong to a file the commit changed.
const APPS = { desktop: /^desktop\//, mobile: /^mobile\// };

/** Whether `flag`'s report covers `relPath`: the desktop and mobile shells, or the web app. */
export function isFlagSource(flag, relPath) {
  if (!isSourceFile(relPath)) return false;
  const app = APPS[flag];
  return app ? app.test(relPath) : !Object.values(APPS).some((re) => re.test(relPath));
}

/**
 * The repository-relative path of a source the coverage names: a path under
 * the root, or a webpack source-map URL (`webpack://falkordb-browser/./app/page.tsx`,
 * `webpack://_N_E/./app/page.tsx?1a2b`), so the server, browser and Node
 * coverage of one file merge into one entry.
 */
export function toSourcePath(url) {
  let p = url.replace(/\\/g, '/');
  if (p.startsWith('file://')) p = fileURLToPath(p).replace(/\\/g, '/');
  const root = ROOT.replace(/\\/g, '/');
  if (p.startsWith(root)) p = p.slice(root.length);
  return p
    .replace(/^webpack:\/\/[^/]*\//, '')
    .replace(/^\.\//, '')
    .replace(/[?#].*$/, '');
}

/**
 * The local copy of a source map the browser asked the server for: the
 * coverage build serves `.next/static/**` at `/_next/static/**`.
 */
export function localSourceMap(url) {
  const m = /^https?:\/\/[^/]+\/_next\/(static\/[^?#]+)/.exec(url);
  return m ? path.join(ROOT, '.next', decodeURIComponent(m[1])) : undefined;
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** The 1-based source lines a source map's `mappings` point into. */
export function mappedLines(mappings) {
  const lines = new Set();
  let line = 0;
  for (const segment of mappings.split(/[;,]/)) {
    if (!segment) continue;
    const fields = [];
    let value = 0;
    let shift = 0;
    for (const char of segment) {
      const digit = BASE64.indexOf(char);
      value += (digit & 31) << shift;
      if (digit & 32) {
        shift += 5;
      } else {
        fields.push(value & 1 ? -(value >>> 1) : value >>> 1);
        value = 0;
        shift = 0;
      }
    }
    if (fields.length >= 4) {
      line += fields[2];
      lines.add(line + 1);
    }
  }
  return lines;
}

/** Compiles TypeScript the way the app's tsconfig does, with a source map. */
async function compile(file, source) {
  const { default: ts } = await import('typescript');
  return ts.transpileModule(source, {
    fileName: file,
    compilerOptions: {
      target: ts.ScriptTarget.ES2022,
      module: ts.ModuleKind.ESNext,
      jsx: ts.JsxEmit.ReactJSX,
      sourceMap: true,
      inlineSources: true,
    },
  });
}

/**
 * The lines of a TypeScript file that hold code: those its compiled output
 * maps back to. Types, imports of types and comments compile to nothing.
 * Every report counts these lines alone, so a file is measured the same
 * whether Node ran it, webpack bundled it or no test loaded it.
 */
async function codeLines(relPath) {
  const file = path.join(ROOT, relPath);
  const out = await compile(file, readFileSync(file, 'utf8'));
  return mappedLines(JSON.parse(out.sourceMapText).mappings);
}

/**
 * TypeScript as the JavaScript Node runs, or undefined when Node cannot strip
 * it. Stripping blanks the types out in place, so the code keeps its offsets.
 */
function stripTypes(source) {
  try {
    return stripTypeScriptTypes(source);
  } catch {
    return undefined;
  }
}

/** A TypeScript file no test loaded, made JavaScript so Monocart can parse it. */
async function transpile(entry) {
  const file = fileURLToPath(entry.url);
  if (!/\.tsx?$/.test(file)) return;
  const stripped = file.endsWith('.ts') ? stripTypes(entry.source) : undefined;
  if (stripped !== undefined) {
    entry.source = stripped;
    return;
  }
  // JSX (or TypeScript Node cannot strip) needs a compile, mapped back.
  const out = await compile(file, entry.source);
  entry.source = out.outputText.replace(/\/\/# sourceMappingURL=.*$/m, '');
  entry.sourceMap = { ...JSON.parse(out.sourceMapText), sources: [entry.url] };
}

/**
 * One page's coverage as e2e/infra/coverage.ts saved it, each entry given back
 * the chunk source saved beside it. An entry whose source was never saved is
 * dropped: without it the coverage cannot be mapped.
 */
export function browserEntries(dir, name) {
  return JSON.parse(readFileSync(path.join(dir, name), 'utf8')).filter((entry) => {
    const sourceFile = path.join(dir, `browser-source-${createHash('sha1').update(entry.url).digest('hex')}.js`);
    try {
      entry.source = readFileSync(sourceFile, 'utf8');
      return true;
    } catch (error) {
      if (error.code === 'ENOENT') return false;
      throw error;
    }
  });
}

/** Writes coverage/<flag>/ from the raw coverage in `dirs`. */
async function main([flag, ...dirs]) {
  if (!flag || !dirs.length) {
    console.error('usage: coverage-report.mjs <flag> <raw dir>...');
    process.exit(2);
  }
  // A source file of this checkout that the flag covers (source maps also
  // name files of dependencies).
  const inScope = (sourcePath) => {
    const rel = toSourcePath(sourcePath);
    return isFlagSource(flag, rel) && existsSync(path.join(ROOT, rel));
  };
  const outputDir = path.join(ROOT, 'coverage', flag);
  const { CoverageReport } = await import('monocart-coverage-reports');
  const report = new CoverageReport({
    name: `${flag} coverage`,
    outputDir,
    baseDir: ROOT,
    reports: [['codecov'], ['v8']],
    entryFilter: (entry) => {
      if (!entry.url.startsWith('file:')) return localSourceMap(entry.url) !== undefined;
      const rel = toSourcePath(entry.url);
      return rel.startsWith('.next/server/') || inScope(rel);
    },
    sourceFilter: inScope,
    // Monocart rewrites a URL into a path before this, turning a webpack
    // `?query` into part of the file name; `info.url` is the URL as written.
    sourcePath: (sourcePath, info) => toSourcePath(info?.url ?? sourcePath),
    sourceMapResolver: async (url, defaultResolver) => {
      const local = localSourceMap(url);
      if (!local) return defaultResolver(url);
      return existsSync(local) ? readFileSync(local, 'utf8') : undefined;
    },
    all: {
      dir: ROOT,
      filter: inScope,
      transformer: transpile,
    },
  });

  for (const dir of dirs) {
    if (!existsSync(dir)) {
      console.warn(`No coverage in ${dir}`);
      continue;
    }
    const names = readdirSync(dir);
    // Node processes: NODE_V8_COVERAGE files.
    if (names.some((n) => n.startsWith('coverage-'))) await report.addFromDir(dir);
    // Browser pages: what e2e/infra/coverage.ts saves, each page's coverage
    // apart from the chunk sources it ran.
    for (const name of names.filter((n) => /^browser-[^.]+\.json$/.test(n))) {
      const entries = browserEntries(dir, name);
      if (entries.length) await report.add(entries);
    }
  }
  await report.generate();
  await normalize(flag, path.join(outputDir, 'codecov.json'));
}

/**
 * Keeps only the code lines of each TypeScript file in the Codecov report,
 * and prints the line coverage Codecov will compute from it.
 */
async function normalize(flag, reportFile) {
  const report = JSON.parse(readFileSync(reportFile, 'utf8'));
  let lines = 0;
  let hits = 0;
  for (const [file, fileLines] of Object.entries(report.coverage)) {
    const code = /\.tsx?$/.test(file) ? await codeLines(file) : undefined;
    for (const [line, count] of Object.entries(fileLines)) {
      if (code && !code.has(Number(line))) {
        delete fileLines[line];
      } else {
        lines += 1;
        // Codecov counts a partially covered line ("1/2") as a partial, not a hit.
        if (typeof count === 'number' ? count > 0 : count.split('/')[0] === count.split('/')[1]) hits += 1;
      }
    }
  }
  writeFileSync(reportFile, JSON.stringify(report));
  const files = Object.keys(report.coverage).length;
  const summary = `${flag}: ${lines ? ((100 * hits) / lines).toFixed(2) : '0.00'}% of lines (${hits}/${lines} in ${files} files)`;
  console.log(summary);
  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `### Coverage\n\n${summary}\n`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await main(process.argv.slice(2));
}
